package kr.workbench;
import java.util.*;
public final class JsAnalysisTest {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}
 static JsAnalysis.Endpoint endpoint(JsAnalysis.Result r,String suffix){return r.endpoints().stream().filter(e->e.url().endsWith(suffix)).findFirst().orElseThrow(()->new AssertionError(r.toString()));}
 public static void main(String[] args){
 String github="ghp_"+"A1b2C3d4".repeat(5);String aws="AKIAIOSFODNN7EXAMPLE";String google="AIza"+"A".repeat(35);
 var r=JsAnalysis.analyze("const ROOT='/api';\nfetch(ROOT+'/orders?token=SECRET_QUERY',{method:'POST',headers:{Authorization:'Bearer DUMMY_SECRET_TOKEN'},body:{orderId:123}});\naxios.post('/upload',{fileId:42},{headers:{'X-API-Key':'MASK_ME_API_KEY'}});\nxhr.open('GET','/profile');new WebSocket('wss://socket.test/events');\nwindow.location.href='/login';\nconst cfg={apiKey:'"+google+"',githubToken:'"+github+"',accessKey:'"+aws+"',password:'your_password'};","https://example.test/app/main.js?secret=BASE_QUERY");
 check(r.status().contains("AST 블록 1"),"AST successfully parsed");var order=endpoint(r,"/api/orders");check(order.method().equals("POST")&&order.complete(),"constant concat fetch URL and method");check(order.headers().contains("Authorization")&&order.bodyKeys().contains("orderId"),"header names and body keys from call options");check(order.parameters().equals("token")&&!r.toString().contains("SECRET_QUERY")&&!r.toString().contains("BASE_QUERY"),"query values excluded from results");check(endpoint(r,"/upload").bodyKeys().contains("fileId"),"Axios post body metadata");check(endpoint(r,"/profile").kind().contains("XHR"),"XHR open URL");check(endpoint(r,"/events").method().equals("UPGRADE"),"WebSocket identified");check(endpoint(r,"/login").kind().equals("location assignment"),"location assignment URL");
 check(r.secrets().stream().anyMatch(s->s.rule().equals("AWS Access Key ID")),"AWS access key pattern");check(r.secrets().stream().anyMatch(s->s.rule().equals("Google API Key")),"Google key pattern");check(r.secrets().stream().anyMatch(s->s.rule().equals("GitHub token")),"GitHub token pattern");check(r.secrets().stream().noneMatch(s->s.rule().contains("password")),"placeholder excluded");check(!r.toString().contains(github)&&!r.toString().contains(google)&&!r.toString().contains(aws),"secret results masked with fingerprints only");
 var dynamic=JsAnalysis.analyze("const root='/v1';fetch(`${root}/users/${userId}`);fetch('/v2/'+accountId);fetch('/x\\x2fy');","https://example.test/");check(dynamic.endpoints().stream().anyMatch(e->e.url().contains("/v1/users/{dynamic}")&&!e.complete()),"template unresolved value retained");check(dynamic.endpoints().stream().anyMatch(e->e.url().endsWith("/v2/{dynamic}")&&!e.complete()),"dynamic concatenation marked unresolved");check(endpoint(dynamic,"/x/y").complete(),"escaped string decoded by parser");
 var scope=JsAnalysis.analyze("const root='/outer';function f(root){fetch(root+'/inside');}fetch(root+'/outside');","");check(scope.endpoints().stream().noneMatch(e->e.url().equals("/outer/inside")),"shadowed parameter not resolved from global const");check(endpoint(scope,"/outer/outside").complete(),"global const resolved in own scope");
 var axios=JsAnalysis.analyze("axios({baseURL:'https://api.test/v1',url:'/users',method:'DELETE',params:{id:123},headers:{'X-Test':'value'}});","");var users=endpoint(axios,"/v1/users");check(users.method().equals("DELETE")&&users.parameters().contains("id"),"Axios baseURL and params metadata");
 var html=JsAnalysis.analyze("<!doctype html>\n<script src='/external.js'></script>\n<script>fetch('/inline');</script>","https://example.test/");check(endpoint(html,"/inline").line()==3,"HTML inline script original line location");check(html.endpoints().stream().anyMatch(e->e.url().endsWith("external.js")&&e.method().equals("?")&&e.kind().contains("src")),"external script URLs remain static candidates with no inferred request method");
 var failed=JsAnalysis.analyze("const apiKey='"+google+"'; fetch( ;","");check(failed.status().contains("AST 실패")&&failed.secrets().size()==1,"parse failure clearly labeled with secret fallback");
 var numeric=JsAnalysis.analyze("fetch('/items/'+(1+2));","");check(numeric.endpoints().stream().noneMatch(e->e.url().endsWith("12")),"numeric arithmetic not incorrectly concatenated");
 var cred=JsAnalysis.analyze("fetch('https://user:PASS_SECRET@api.test/list?key=QUERY_SECRET#FRAGMENT_SECRET');","");check(!cred.toString().contains("PASS_SECRET")&&!cred.toString().contains("QUERY_SECRET")&&!cred.toString().contains("FRAGMENT_SECRET"),"URL credentials query and fragment excluded");
 var cap=JsAnalysis.analyze("fetch('/ok');"+" ".repeat(JsAnalysis.SOURCE_LIMIT),"");check(cap.truncated(),"source size limit explicit");
 var many=new StringBuilder();for(int i=0;i<650;i++)many.append("fetch('/item").append(i).append("');");var limited=JsAnalysis.analyze(many.toString(),"");check(limited.endpoints().size()==500&&limited.truncated(),"endpoint result cap");
 check(JsAnalysis.analyze("throw new Error('MUST_NOT_EXECUTE'); fetch('/after');","").endpoints().size()==1,"JavaScript is parsed without executing throw");
 var module=JsAnalysis.analyze("import x from 'x';fetch('/module/api');","");check(module.status().contains("구문 호환")&&module.endpoints().stream().anyMatch(e->e.url().equals("/module/api")&&e.method().equals("GET")&&e.complete()),"module compatibility retains call metadata without execution");
 var requestObject=JsAnalysis.analyze("fetch(new Request('/request',{method:'PUT'}));","");check(endpoint(requestObject,"/request").method().equals("PUT"),"Request constructor URL metadata");
 check(JsAnalysis.analyze("fetch('/a');fetch('/a');","").endpoints().size()==2,"same URL in separate call sites retains code locations");
 check(endpoint(JsAnalysis.analyze("window.open('/popup','_blank');", ""),"/popup").kind().equals("window.open"),"window.open target not confused with XHR");
 System.out.println("JsAnalysisTest: "+checks+" checks passed");
 }
}
